import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mul, add, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-collection-card-3-label';

  // ============================================================================
  // 1. BUILD STAGE BACKDROP (gradient surface, ~7x6 units at z=-2.5)
  // ============================================================================
  const stageGeo = new PlaneGeometry(7, 6);
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Engineered vertical gradient: surface (dark bottom) -> paper (light top)
  const gradientStops = [
    { position: 0, color: colors.surface },
    { position: 1, color: colors.paper }
  };

  const stageUvNode = uv();
  const gradientNode = stageUvNode.y; // vertical gradient (0 at bottom, 1 at top)

  // Smooth interpolation between gradient stops
  const color0 = vec3(0.043, 0.043, 0.063); // #0b0b10 (surface)
  const color1 = vec3(0.91, 0.925, 0.949); // #e8ecf2 (paper)
  const stageColorNode = add(
    mul(color0, add(1, mul(gradientNode, -1))),
    mul(color1, gradientNode)
  );

  const stageMat = new MeshBasicNodeMaterial({
    colorNode: stageColorNode,
    side: 1 // DoubleSide
  });
  const stagePlane = new Mesh(stageGeo, stageMat);
  stagePlane.position.z = -2.5;
  stagePlane.renderOrder = -10;
  group.add(stagePlane);

  // ============================================================================
  // 2. LOAD IMAGE & CREATE CARD PLANE
  // ============================================================================
  const cardGeo = new PlaneGeometry(2.4, 1.5);
  let cardMat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    side: 1
  });
  const cardMesh = new Mesh(cardGeo, cardMat);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.colorNode = texture(tex);
      cardMat.needsUpdate = true;
    });
  }

  cardMesh.position.copy(new Vector3(3.2, 1, 0.06));
  cardMesh.renderOrder = 10;
  group.add(cardMesh);

  // ============================================================================
  // 3. RENDER TEXT: "Collection 3" (headline, 39px 400)
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((item) => item.role === 'headline');

  if (headlineItem) {
    const textContent = headlineItem.text || 'Collection 3';
    const fontSize = headlineItem.typography?.fontSize || 39;

    const headlineText = ctx.fontAtlas.createText(textContent, {
      fontSize: fontSize,
      color: colors.ink, // #16161d
      align: 'center',
      letterSpacingPx: 2
    });

    headlineText.position.set(3.2, 1, 0.1);
    headlineText.renderOrder = 15;
    group.add(headlineText);
  }

  // ============================================================================
  // 4. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    stageGeo.dispose();
    stageMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
  };

  return group;
}
